import pytest
import json
from pathlib import Path
from validator import SwaggerSchemaValidator

# Load test data from JSON file
_here = Path(__file__).resolve().parent
_ENDPOINT_TEST_DATA_PATH = _here / 'pet.json'
with open(_ENDPOINT_TEST_DATA_PATH) as f:
    _ENDPOINT_TEST_DATA = json.load(f)

# Initialize the SwaggerSchemaValidator with the API spec
swagger_validator = SwaggerSchemaValidator('api.json')

@pytest.mark.parametrize("scenario_case", _ENDPOINT_TEST_DATA, ids=[data['scenario'] for data in _ENDPOINT_TEST_DATA])
def test_update_pet(api_client, host, petstore_auth, scenario_case):
    """
    Test updating a pet using the /pet endpoint with various scenarios.
    """
    endpoint = '/pet'
    headers = {'Authorization': f"Bearer {petstore_auth}"}
    data = {key: scenario_case[key] for key in ['name', 'photoUrls'] if key in scenario_case}
    
    # Add optional data if present in scenario
    if 'id' in scenario_case:
        data['id'] = scenario_case['id']
    if 'category' in scenario_case:
        data['category'] = scenario_case['category']
    if 'tags' in scenario_case:
        data['tags'] = scenario_case['tags']
    if 'status' in scenario_case:
        data['status'] = scenario_case['status']
    
    # Validate request data against the schema
    request_validation_result = swagger_validator.validate_json(data, 'Pet')
    assert request_validation_result['valid'], f"Request validation failed: {request_validation_result.get('message', '')}"

    # Make the PUT request to update the pet
    response = api_client.put(endpoint, headers=headers, data=json.dumps(data))
    
    # Validate response status code
    assert response.status_code == scenario_case['statusCode'], f"Unexpected status code: {response.status_code}"

    # Validate response schema
    response_validation_result = swagger_validator.validate_schema_by_response(endpoint, 'PUT', str(response.status_code), response)
    assert response_validation_result['valid'], f"Response validation failed: {response_validation_result.get('message', '')}"

